def moving_average(values: list, window: int) -> list:
    if window <= 0:
        raise ValueError("Window size must be positive.")

    n = len(values)
    if n == 0:
        return []

    result = [None] * (min(window-1, n))
    for i in range(window-1, n):
        avg = sum(values[i-window+1:i+1]) / window
        result.append(avg)

    return result

